import{_ as d,o as r,c as a,a5 as e}from"./chunks/framework.R-FQ1xZ2.js";const g=JSON.parse('{"title":"路线总览","description":"","frontmatter":{"title":"路线总览"},"headers":[],"relativePath":"roadmap/index.md","filePath":"roadmap/index.md","lastUpdated":null}'),o={name:"roadmap/index.md"};function h(n,t,l,s,i,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="学习路线总览" tabindex="-1">学习路线总览 <a class="header-anchor" href="#学习路线总览" aria-label="Permalink to &quot;学习路线总览&quot;">​</a></h1><h2 id="一、我要去哪" tabindex="-1">一、我要去哪 <a class="header-anchor" href="#一、我要去哪" aria-label="Permalink to &quot;一、我要去哪&quot;">​</a></h2><p><strong>目标岗位（三选一，但共用同一份能力底座）</strong></p><table tabindex="0"><thead><tr><th>岗位</th><th>面试官真正想看的东西</th><th>对应的层</th></tr></thead><tbody><tr><td>大模型开发工程师</td><td>懂原理、能训能推、能算显存与成本</td><td>L1 + L5 + L7</td></tr><tr><td>AI Agent 开发工程师</td><td>能编排、能控状态、能兜底、工具契约扎实</td><td>L4 + L2 + L5</td></tr><tr><td>AI 应用开发工程师</td><td>能落地、能评测、能上线、能讲清取舍</td><td>L3 + L5 + L6</td></tr></tbody></table><p>三个岗位的共同底座是 <strong>L3 RAG + L4 Agent + L6 评测</strong>。这三层就是我的主战场。</p><h2 id="二、总量核算" tabindex="-1">二、总量核算 <a class="header-anchor" href="#二、总量核算" aria-label="Permalink to &quot;二、总量核算&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>知识点</th><th>估算学时</th></tr></thead><tbody><tr><td>L0</td><td>编程与工程基础</td><td>30</td><td>≈148h</td></tr><tr><td>L1</td><td>大模型原理</td><td>24</td><td>≈103h</td></tr><tr><td>L2</td><td>提示工程与结构化输出</td><td>22</td><td>≈71h</td></tr><tr><td>L3</td><td>RAG 与检索</td><td>28</td><td>≈105h</td></tr><tr><td>L4</td><td>Agent 与工具生态</td><td>33</td><td>≈118h</td></tr><tr><td>L5</td><td>工程化与服务部署</td><td>24</td><td>≈84h</td></tr><tr><td>L6</td><td>评测与可观测</td><td>14</td><td>≈28h</td></tr><tr><td>L7</td><td>进阶：微调 / 推理优化 / 多模态</td><td>10</td><td>≈50h</td></tr><tr><td><strong>合计</strong></td><td></td><td><strong>185</strong></td><td><strong>≈707h</strong></td></tr></tbody></table><p>学时口径：从零基础到「能在面试中讲清楚并有代码产出」的净学习时间，<strong>不含反复练习与查资料</strong>。实际投入建议 ×1.5。</p><p>按每周 12 小时（课内 8h + 周末 4h）≈ 59 周；按每周 18 小时（含假期冲刺）≈ 40 周。</p><div class="warning custom-block"><p class="custom-block-title">时间线：先确认再照做</p><p>这个站点建立于 <strong>2026-10-04</strong>。2027 届的招聘窗口是：</p><ul><li><strong>提前批</strong> 2026 年 7—9 月（已过）</li><li><strong>正式批</strong> 2026 年 9—11 月（<strong>就在现在</strong>）</li><li><strong>春招补录</strong> 2027 年 3—5 月</li><li><strong>毕业</strong> 2027 年 6—7 月</li></ul><p>所以真正的硬约束不是「学完 707 小时」，而是<strong>投递窗口</strong>。下面的阶段划分按这个现实重排过：<strong>先补能直接进面试口述与答题的部分，再补需要长期投入的部分。</strong></p></div><h2 id="三、三阶段-按投递窗口倒排" tabindex="-1">三、三阶段（按投递窗口倒排） <a class="header-anchor" href="#三、三阶段-按投递窗口倒排" aria-label="Permalink to &quot;三、三阶段（按投递窗口倒排）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>主题</th><th>目标状态</th></tr></thead><tbody><tr><td><strong>A：面试止血</strong></td><td>现在 → 2026-11（≈6 周）</td><td>L4 + L3 + L6 的<strong>高频考点</strong>，配我两个真实项目的深挖话术</td><td>任何一场面试问到我的项目与 RAG/Agent 基础，都能答到三层追问</td></tr><tr><td><strong>B：补齐底座</strong></td><td>2026-11 → 2027-02（≈14 周）</td><td>L1 + L2 + L5 系统化补，L0 按需补（编码面单独刷）</td><td>能解释上层现象、能算显存与成本、能讲清工程取舍</td></tr><tr><td><strong>C：拉差距</strong></td><td>2027-02 → 2027-05（≈14 周）</td><td>L7（SFT / LoRA / DPO / GRPO / 推理优化）+ 把两个项目再往深做一轮</td><td>有微调与推理优化的真实数据，和「只会调 API」的人拉开距离</td></tr></tbody></table><p><strong>每周固定节奏</strong>：2h 读原理 + 6h 写代码 + 2h 写文档（README / 评测报告 / 笔记）+ 2h 复盘。</p><blockquote><p>那 2 小时写文档的时间不能省 —— <strong>简历素材与面试话术全部产自这 2 小时</strong>。学了但不写下来，等于没学。</p></blockquote><h2 id="四、阶段-a-的六周-最高优先级-每周一个硬性交付物" tabindex="-1">四、阶段 A 的六周（最高优先级，每周一个硬性交付物） <a class="header-anchor" href="#四、阶段-a-的六周-最高优先级-每周一个硬性交付物" aria-label="Permalink to &quot;四、阶段 A 的六周（最高优先级，每周一个硬性交付物）&quot;">​</a></h2><p>顺序不是「章节顺序」，而是<strong>交付物顺序</strong>。每周必须产出一个能被面试官看到的东西。</p><table tabindex="0"><thead><tr><th>周</th><th>主题</th><th>本周交付物（硬性）</th><th>本项目里的落点</th></tr></thead><tbody><tr><td>第 1 周</td><td>Agent 骨架与状态机</td><td>把 YYHelp 主图的节点、边、终止条件<strong>默画</strong>出来并讲清每个节点的职责</td><td><a href="/learn/projects/yyhelp/03-architecture.html">YYHelp 总体架构</a></td></tr><tr><td>第 2 周</td><td>ReAct 循环与工具契约</td><td>讲清 <code>@tool</code> + pydantic 校验、幂等键、人工确认的完整链路</td><td><a href="/learn/projects/yyhelp/09-tools-mcp.html">工具层与 MCP</a></td></tr><tr><td>第 3 周</td><td>检索层与中文 BM25 陷阱</td><td>复现「Milvus 默认 analyzer 导致中文 BM25 静默返回空」这个故障</td><td><a href="/learn/projects/yyhelp/08-retrieval.html">YYHelp 检索层</a></td></tr><tr><td>第 4 周</td><td>Rerank 与上下文组装</td><td>拿出「加 Rerank 前后」的检索指标对比（至少两个数）</td><td><a href="/learn/projects/rag/05-rerank.html">重排与上下文组装</a></td></tr><tr><td>第 5 周</td><td>评测与统计检验</td><td>讲清配对 t / Wilcoxon / Holm 校正 / 效应量门槛 / 三态退出码</td><td><a href="/learn/projects/yyhelp/11-evaluation.html">YYHelp 评测与回归门禁</a></td></tr><tr><td>第 6 周</td><td>项目答辩预演</td><td>20 问答辩稿，每题能追三层</td><td><a href="/learn/projects/yyhelp/17-interview.html">面试深挖与口径</a></td></tr></tbody></table><p><strong>第 6 周结束的验收线</strong>：能用 3 分钟讲清「我的系统怎么工作 / 我改过什么 / 数据上是变好还是变差」，三个问题都拿得出数字。</p><h2 id="五、长期路线-阶段-b-c-的周计划" tabindex="-1">五、长期路线（阶段 B / C 的周计划） <a class="header-anchor" href="#五、长期路线-阶段-b-c-的周计划" aria-label="Permalink to &quot;五、长期路线（阶段 B / C 的周计划）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>周次（相对）</th><th>主题</th><th>覆盖</th><th>里程碑</th></tr></thead><tbody><tr><td>+1 ~ +3</td><td>Transformer 与注意力</td><td>L1-01~L1-09</td><td>白板画出 Transformer 并解释每一块</td></tr><tr><td>+4 ~ +5</td><td>Tokenizer + 解码 + KV Cache</td><td>L1-02、L1-03、L1-10、L1-11、L1-20</td><td>手写 BPE + 手写采样器；算清 KV Cache 显存</td></tr><tr><td>+6 ~ +8</td><td>训练三阶段 + 微调原理</td><td>L1-12~L1-17、L1-23、L1-24</td><td>讲清 SFT / RLHF / LoRA 的取舍</td></tr><tr><td>+9 ~ +12</td><td>Prompt 工程与结构化输出</td><td>L2-01~L2-22</td><td>一套带版本号与评测结果的 prompt 库</td></tr><tr><td>+13 ~ +18</td><td>工程化与服务部署</td><td>L5-01~L5-24</td><td>主项目 Docker 一键起 + 压测报告 + 成本报告</td></tr><tr><td>+19 ~ +24</td><td>微调进阶 + 评测门禁</td><td>L7-01~L7-08、L6-12</td><td>一次真实 LoRA 微调 + CI 评测门禁</td></tr><tr><td>+25 ~ +28</td><td>简历定稿 / 话术 / 模拟面试</td><td>全层回顾</td><td>三方向各一份简历 + 主项目 20 问答辩稿</td></tr></tbody></table><h2 id="六、编码面单开一条线" tabindex="-1">六、编码面单开一条线 <a class="header-anchor" href="#六、编码面单开一条线" aria-label="Permalink to &quot;六、编码面单开一条线&quot;">​</a></h2><p>L0 里的数据结构与算法<strong>不能靠「学完再看」</strong>，必须每天固定时间刷。建议：</p><ul><li>每天 1 题，周末 3 题，维持 8 个月 → 约 320 题</li><li>高频顺序：数组 / 双指针 → 哈希 → 链表 → 二叉树 → 栈与队列 → 动态规划 → 图与搜索</li><li>刷题时<strong>同时把每题的「思路一句话 + 复杂度 + 易错点」写进笔记</strong>，面试前直接翻</li></ul><div class="tip custom-block"><p class="custom-block-title">下一步</p><ul><li><a href="/learn/roadmap/progress.html">进度看板</a> —— 打勾用，知道自己走到哪了</li><li><a href="/learn/roadmap/how-to-use.html">如何使用这个站</a> —— 右侧助教能读我的笔记，用法在那一页</li></ul></div>',24)])])}const L=d(o,[["render",h]]);export{g as __pageData,L as default};
